/// Builds an object from pairs, keeping their order.
#[macro_export]
macro_rules! jobj {
    () => { $crate::json::Value::Obj($crate::json::Map::new()) };
    ($($k:expr => $v:expr),+ $(,)?) => {{
        let mut m = $crate::json::Map::new();
        $( m.insert($k, $crate::json::Value::from($v)); )+
        $crate::json::Value::Obj(m)
    }};
}

