#!/usr/bin/env python3
"""Run sessions (lists of --cmd) on both programs; compare normalized stdout/stderr/code and the saved file.
usage: suite.py casefile [-v] [-k substring]
casefile: one case per line: commands separated by ' ;; ' ; a line starting with '@file path' copies+opens that project first.
Lines starting with # are comments. 'inspect' outputs are reduced to the phase keys.
"""
import os, re, subprocess, sys, tempfile, shutil, json, difflib
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/tmp/styles-agent/phasing/repo/target/release/bimcraft-cli')
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
KEYS = ['option_sets', 'phase_filters', 'phase_overrides', 'phases', 'history']
def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return GUID.sub(rep, s)
def reduce_inspect(out):
    lines = []
    for l in out.split('\n'):
        if l.startswith('{"counts"'):
            try:
                d = json.loads(l)
                l = json.dumps({k: d.get(k) for k in KEYS}, ensure_ascii=False, sort_keys=True)
            except Exception:
                pass
        lines.append(l)
    return '\n'.join(lines)
def run(exe, cmds, openfile):
    d = tempfile.mkdtemp(prefix='su')
    args = [exe, 'run']
    if openfile:
        shutil.copy(openfile, os.path.join(d, 'in.bimcraft'))
        args.append('in.bimcraft')
    for c in cmds: args += ['--cmd', c]
    args += ['--save', 'x.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True, timeout=60)
    f = os.path.join(d, 'x.bimcraft')
    saved = open(f).read() if os.path.exists(f) else ''
    shutil.rmtree(d)
    return p.returncode, reduce_inspect(p.stdout.decode('utf-8', 'replace')), p.stderr.decode('utf-8', 'replace'), saved
def main():
    args = sys.argv[1:]
    verbose = '-v' in args
    filt = None
    if '-k' in args: filt = args[args.index('-k') + 1]
    cases = []
    openfile = None
    for line in open(args[0]).read().split('\n'):
        if not line.strip() or line.startswith('#'): continue
        if line.startswith('@file '):
            openfile = line[6:].strip() or None
            continue
        cases.append((openfile, line))
    bad = 0
    for of, line in cases:
        if filt and filt not in line: continue
        cmds = [c.strip() for c in line.split(' ;; ')]
        o = run(ORIG, cmds, of)
        m = run(MINE, cmds, of)
        diffs = []
        for name, x, y in (('code', str(o[0]), str(m[0])), ('stdout', norm(o[1]), norm(m[1])), ('stderr', norm(o[2]), norm(m[2])), ('file', norm(o[3]), norm(m[3]))):
            if x != y:
                diffs.append((name, x, y))
        if diffs:
            bad += 1
            print('DIFF:', line[:300])
            for name, x, y in diffs:
                print('  --', name)
                for l in list(difflib.unified_diff(x.splitlines(), y.splitlines(), 'orig', 'mine', lineterm='', n=0))[2:14]:
                    print('    ', l[:400])
        elif verbose:
            print('same:', line[:200])
    print('%d/%d differ' % (bad, len([c for c in cases if not filt or filt in c[1]])))
main()

