#!/usr/bin/env python3
"""Random sessions of phase / phase_filter / option commands, compared between the original and mine."""
import random, json, subprocess, sys, os
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
n = int(sys.argv[2]) if len(sys.argv) > 2 else 100
fx = sys.argv[3] if len(sys.argv) > 3 else None
random.seed(seed)
PH = ['Existing', 'New Construction', 'Demo', 'Pre', 'X', ' Demo ', '', 'existing', 3, None]
FL = ['Show All', 'Show New', 'Mine', 'Show Complete', '', 7, None]
SH = ['by-category', 'overridden', 'not-displayed', 'bogus', 5, None]
SETS = ['Kitchen', 'Bath', 'K:x', '', None, 4]
OPTS = ['A', 'B', 'C', 'A:x', '', 5]
def r(xs): return random.choice(xs)
def ovr():
    o = {}
    for k in random.sample(['halftone', 'hidden', 'transparency', 'projection', 'cut', 'shown', 'bogus'], random.randint(0, 3)):
        if k in ('halftone', 'hidden', 'shown'): o[k] = r([True, False, None, 5])
        elif k == 'transparency': o[k] = r([0, 50, 150, None, 'x'])
        elif k == 'bogus': o[k] = 1
        else:
            s = {}
            for kk in random.sample(['color', 'weight', 'dash', 'fill', 'foreground'], random.randint(0, 2)):
                if kk == 'color': s[kk] = r([[1, 2, 3], '#ff0000', 'red', None])
                elif kk == 'weight': s[kk] = r([3, 17, 2.5, None])
                elif kk == 'dash': s[kk] = r(['dashed', 'zig', None])
                elif kk == 'fill': s[kk] = r([[9, 9, 9], None])
                else: s[kk] = r([{'pattern': 'Sand'}, {'pattern': None}, {'pattern': 'Nope'}, None])
            o[k] = r([s, None, 5])
    return o
def phase_cmd():
    p = {}
    for k in random.sample(['name', 'before', 'after', 'rename', 'delete', 'into', 'now', 'overrides'], random.randint(0, 3)):
        if k == 'delete': p[k] = r([True, False, None, 1])
        elif k == 'overrides': p[k] = r([{r(['new', 'existing', 'demolished', 'temporary', 'bogus']): r([ovr(), None])}, {}, 5, None])
        else: p[k] = r(PH)
    return 'phase ' + json.dumps(p)
def filter_cmd():
    p = {}
    if random.random() < 0.9: p['name'] = r(FL)
    for k in random.sample(['new', 'existing', 'demolished', 'temporary', 'delete'], random.randint(0, 2)):
        p[k] = r([True, False, 1]) if k == 'delete' else r(SH)
    return 'phase_filter ' + json.dumps(p)
def option_cmd():
    p = {}
    if random.random() < 0.85: p['set'] = r(SETS)
    for k in random.sample(['options', 'primary', 'option', 'rename', 'delete', 'accept', 'now'], random.randint(0, 3)):
        if k == 'options': p[k] = r([random.sample(OPTS, random.randint(0, 3)), 'A', None, []])
        elif k in ('delete', 'accept'): p[k] = r([True, False, None, 'x'])
        elif k == 'now': p[k] = r(['Kitchen: A', 'Kitchen: B', 'Bath: C', None, 5, 'Kitchen:A'])
        else: p[k] = r(OPTS + SETS)
    return 'option ' + json.dumps(p)
cases = []
for i in range(n):
    cmds = []
    if random.random() < 0.5:
        cmds.append('option {"set":"Kitchen","options":["A","B"]}')
    for j in range(random.randint(1, 5)):
        cmds.append(r([phase_cmd, filter_cmd, option_cmd, option_cmd])())
    cmds.append('inspect')
    cases.append(' ;; '.join(cmds))
fn = '/tmp/styles-agent/phasing/fuzz_%d.txt' % seed
with open(fn, 'w') as f:
    if fx: f.write('@file %s\n' % fx)
    f.write('\n'.join(cases) + '\n')
os.execvp('python3', ['python3', '/tmp/styles-agent/phasing/suite.py', fn])

