736	/// Deletes elements and what goes with them: the doors and windows of walls, what is hosted by
737	/// what goes (tags, railings, spot elevations, bars), dimensions left with fewer than two
738	/// references. The ids that went, in order.
739	pub fn delete_with_dependants(pr: &mut Project, ids: &BTreeSet<u64>) -> Vec<u64> {
740	    let mut gone: BTreeSet<u64> = ids.iter().copied().filter(|id| pr.elements.contains_key(id)).collect();
741	    loop {
742	        let guids: BTreeSet<String> = gone.iter().filter_map(|id| pr.guid_of(*id)).collect();
743	        let mut more = Vec::new();
744	        for (id, e) in &pr.elements {
745	            if gone.contains(id) {
746	                continue;
747	            }
748	            let hosted = ["host", "wall"].iter().any(|k| e.get(k).and_then(|h| h.as_str()).map(|h| guids.contains(h)).unwrap_or(false));
749	            let dim_left = match e.get("refs").and_then(|r| r.as_arr()) {
750	                Some(refs) if cat(e) == "dimension" => {
751	                    let n = refs.len();
752	                    let lost = refs
753	                        .iter()
754	                        .filter(|r| r.get("id").and_then(|x| x.as_str()).map(|g| guids.contains(g)).unwrap_or(false))
755	                        .count();
756	                    lost > 0 && n - lost < 2
757	                }
758	                _ => false,
759	            };
760	            if hosted || dim_left {
761	                more.push(*id);
762	            }
763	        }
764	        if more.is_empty() {
765	            break;
766	        }
767	        gone.extend(more);
768	    }
769	    let guids: BTreeSet<String> = gone.iter().filter_map(|id| pr.guid_of(*id)).collect();
770	    for id in &gone {
771	        pr.elements.remove(id);
772	    }
773	    // dimensions lose what went
774	    for e in pr.elements.values_mut() {
775	        if cat(e) != "dimension" {
776	            continue;
777	        }
778	        if let Some(Value::Arr(refs)) = e.get_mut("refs") {
779	            refs.retain(|r| !r.get("id").and_then(|x| x.as_str()).map(|g| guids.contains(g)).unwrap_or(false));
780	        }
781	    }
782	    gone.into_iter().collect()
783	}
